from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
REPAIR = ROOT / "runtime/shinobi_runtime/api/repair.py"
text = REPAIR.read_text(encoding="utf-8")


def replace_once(old: str, new: str) -> None:
    global text
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"expected one match, found {count}: {old[:120]!r}")
    text = text.replace(old, new, 1)


def replace_between(start: str, end: str, new: str) -> None:
    global text
    i = text.find(start)
    if i < 0:
        raise SystemExit(f"start marker missing: {start!r}")
    j = text.find(end, i)
    if j < 0:
        raise SystemExit(f"end marker missing: {end!r}")
    text = text[:i] + new + text[j:]


replace_once(
    '''"""Privileged forward-only repair of one committed campaign transaction.\n\nA repair never rewrites Git history and never accepts arbitrary repository refs\nor paths from a caller.  The damaged transaction id is resolved through its\nimmutable Shinobi commit trailers; only that commit's exact ``state/`` paths are\nrestored from its first parent, while ``state/meta.json`` advances to a new\nrevision.  Current source files are therefore preserved.\n"""''',
    '''"""Privileged forward-only repair of committed campaign transactions.\n\nA repair never rewrites Git history and never accepts arbitrary repository refs\nor paths from a caller. A caller may identify either one damaged transaction or\na bounded, contiguous first-parent chain ending at the current state revision.\nEvery transaction is resolved through immutable Shinobi commit trailers; only\nthe union of that chain's exact ``state/`` paths is restored from the first\nparent of the oldest damaged transaction, while ``state/meta.json`` advances to\na new revision. Current source files are therefore preserved.\n"""''',
)

replace_once(
    '''_META_PATH = "state/meta.json"\n''',
    '''_META_PATH = "state/meta.json"\n_MAX_REPAIR_CHAIN = 32\n''',
)

replace_once(
    '''class CampaignRepairService:\n    """Execute one bounded forward repair through the normal transaction coordinator."""\n''',
    '''class CampaignRepairService:\n    """Execute one bounded provenance repair through the normal coordinator."""\n''',
)

replace_between(
    '''    def _require_base(self, command: CommandEnvelope, *, require_revision: bool = True) -> str:\n''',
    '''    def _require_fresh_deployment(self) -> None:\n''',
    '''    def _require_base(self, command: CommandEnvelope, *, require_revision: bool = True) -> tuple[str, ...]:\n        if command.mode != REPAIR_MODE or command.command_type != REPAIR_COMMAND_TYPE:\n            raise OperationError(403, "repair_mode_required")\n        if command.actor_id not in self.operations.allowed_actor_ids:\n            raise OperationError(403, "actor_not_allowed")\n\n        keys = set(command.payload)\n        if keys == {"damaged_transaction_id"}:\n            raw_ids: Any = [command.payload.get("damaged_transaction_id")]\n        elif keys == {"damaged_transaction_ids"}:\n            raw_ids = command.payload.get("damaged_transaction_ids")\n            if not isinstance(raw_ids, list) or not 1 <= len(raw_ids) <= _MAX_REPAIR_CHAIN:\n                raise OperationError(422, "repair_payload_invalid")\n        else:\n            raise OperationError(422, "repair_payload_invalid")\n\n        transaction_ids: list[str] = []\n        seen: set[str] = set()\n        for raw in raw_ids:\n            if (\n                not isinstance(raw, str)\n                or not raw.startswith("tx.")\n                or len(raw) > 160\n                or raw in seen\n            ):\n                raise OperationError(422, "repair_payload_invalid")\n            seen.add(raw)\n            transaction_ids.append(raw)\n        if not transaction_ids:\n            raise OperationError(422, "repair_payload_invalid")\n\n        try:\n            self.repository.require_campaign(command.campaign_id, _META_PATH)\n            if require_revision:\n                self.repository.require_revision(command.expected_revision, _META_PATH)\n        except StaleRevisionError as exc:\n            raise OperationError(409, "stale_revision") from exc\n        except (TypeError, ValueError) as exc:\n            raise OperationError(409, "repair_campaign_mismatch") from exc\n        return tuple(transaction_ids)\n\n''',
)

replace_between(
    '''    def _build(self, command: CommandEnvelope) -> _RepairPlan:\n''',
    '''    def preview(self, command: CommandEnvelope) -> Mapping[str, Any]:\n''',
    '''    def _build(self, command: CommandEnvelope) -> _RepairPlan:\n        damaged_transaction_ids = self._require_base(command)\n        self._require_fresh_deployment()\n        git = self.coordinator.git\n        head = git.head()\n\n        damaged_records: list[Any] = []\n        revisions: list[int] = []\n        for transaction_id in damaged_transaction_ids:\n            damaged = git.find_transaction_commit(transaction_id)\n            if damaged is None:\n                raise OperationError(404, "repair_transaction_not_found")\n            revision = self._revision_trailer(damaged)\n            if (\n                damaged.trailers.get(TRANSACTION_TRAILER) != transaction_id\n                or damaged.trailers.get(CAMPAIGN_TRAILER) != command.campaign_id\n                or damaged.trailers.get(MODE_TRAILER) not in {"gameplay", "autonomous"}\n                or _META_PATH not in damaged.paths\n                or any(not path.startswith("state/") for path in damaged.paths)\n                or not git.is_ancestor(damaged.commit_hash, head)\n            ):\n                raise OperationError(409, "repair_provenance_invalid")\n            damaged_records.append(damaged)\n            revisions.append(revision)\n\n        first_revision = command.expected_revision - len(damaged_records) + 1\n        expected_revisions = list(range(first_revision, command.expected_revision + 1))\n        if revisions != expected_revisions:\n            raise OperationError(409, "repair_provenance_invalid")\n\n        # A chain repair is intentionally stricter than general ancestry: the\n        # damaged state transactions themselves must be an exact first-parent\n        # sequence. This prevents a caller from skipping an intervening state\n        # mutation or selecting unrelated historical commits. Source-only commits\n        # may exist after the newest damaged transaction because state-tree\n        # equality below proves they did not mutate campaign truth.\n        for older, newer in zip(damaged_records, damaged_records[1:]):\n            if git.first_parent(newer.commit_hash) != older.commit_hash:\n                raise OperationError(409, "repair_provenance_invalid")\n\n        newest = damaged_records[-1]\n        if git.tree_oid(head, "state") != git.tree_oid(newest.commit_hash, "state"):\n            raise OperationError(409, "repair_base_changed")\n\n        restore_commit = git.first_parent(damaged_records[0].commit_hash)\n        restore_meta_raw = git.read_path_at(restore_commit, _META_PATH)\n        newest_meta_raw = git.read_path_at(newest.commit_hash, _META_PATH)\n        if restore_meta_raw is None or newest_meta_raw is None:\n            raise OperationError(409, "repair_provenance_invalid")\n        try:\n            restore_meta = json.loads(restore_meta_raw.decode("utf-8"))\n            newest_meta = json.loads(newest_meta_raw.decode("utf-8"))\n        except (UnicodeDecodeError, json.JSONDecodeError) as exc:\n            raise OperationError(409, "repair_provenance_invalid") from exc\n        if (\n            not isinstance(restore_meta, dict)\n            or not isinstance(newest_meta, dict)\n            or restore_meta.get("campaign_id") != command.campaign_id\n            or newest_meta.get("campaign_id") != command.campaign_id\n            or restore_meta.get("revision") != first_revision - 1\n            or newest_meta.get("revision") != command.expected_revision\n        ):\n            raise OperationError(409, "repair_provenance_invalid")\n\n        # Verify every intermediate transaction's own meta after-image matches\n        # its immutable revision trailer. The first-parent check alone proves\n        # commit order, while this proves world-revision continuity.\n        for damaged, revision in zip(damaged_records, revisions):\n            meta_raw = git.read_path_at(damaged.commit_hash, _META_PATH)\n            if meta_raw is None:\n                raise OperationError(409, "repair_provenance_invalid")\n            try:\n                meta = json.loads(meta_raw.decode("utf-8"))\n            except (UnicodeDecodeError, json.JSONDecodeError) as exc:\n                raise OperationError(409, "repair_provenance_invalid") from exc\n            if (\n                not isinstance(meta, dict)\n                or meta.get("campaign_id") != command.campaign_id\n                or meta.get("revision") != revision\n            ):\n                raise OperationError(409, "repair_provenance_invalid")\n\n        affected_paths = tuple(sorted({\n            path for damaged in damaged_records for path in damaged.paths\n        }))\n        writes: dict[str, Optional[bytes]] = {}\n        for path in affected_paths:\n            desired = git.read_path_at(restore_commit, path)\n            if path == _META_PATH:\n                repaired_meta = dict(restore_meta)\n                repaired_meta["revision"] = command.expected_revision + 1\n                desired = (\n                    json.dumps(repaired_meta, ensure_ascii=False, indent=2) + "\\n"\n                ).encode("utf-8")\n            current = self.repository.read_optional_bytes(path)\n            if current != desired:\n                writes[path] = desired\n        if _META_PATH not in writes:\n            raise OperationError(409, "repair_provenance_invalid")\n\n        result: dict[str, Any] = {\n            "repair_kind": (\n                "forward_transaction_repair"\n                if len(damaged_records) == 1\n                else "forward_transaction_chain_repair"\n            ),\n            "restored_state_revision": first_revision - 1,\n            "committed_revision": command.expected_revision + 1,\n            "restored_world_time": restore_meta.get("time"),\n            "restore_commit": restore_commit,\n            "repaired_path_count": len(writes),\n        }\n        if len(damaged_records) == 1:\n            result.update({\n                "damaged_revision": command.expected_revision,\n                "damaged_transaction_id": damaged_transaction_ids[0],\n                "damaged_commit": newest.commit_hash,\n            })\n        else:\n            result.update({\n                "damaged_revision_start": first_revision,\n                "damaged_revision_end": command.expected_revision,\n                "damaged_transaction_ids": list(damaged_transaction_ids),\n                "damaged_commits": [record.commit_hash for record in damaged_records],\n            })\n\n        return _RepairPlan(\n            transaction_id="tx.repair." + command.digest,\n            created_at=command.submitted_at,\n            writes=writes,\n            result=result,\n            affected_refs=tuple(sorted(writes)),\n        )\n\n''',
)

REPAIR.write_text(text, encoding="utf-8")

TEST = ROOT / "tests/current/test_forward_campaign_repair_chain.py"
TEST.write_text('''from __future__ import annotations\n\nimport hashlib\nimport json\nfrom contextlib import nullcontext\nfrom pathlib import Path\n\nimport pytest\n\nfrom shinobi_runtime.api.operations import OperationError\nfrom shinobi_runtime.api.repair import CampaignRepairService, REPAIR_COMMAND_TYPE\nfrom shinobi_runtime.commands import CommandEnvelope\nfrom shinobi_runtime.tx.git import (\n    CAMPAIGN_TRAILER, MODE_TRAILER, REVISION_TRAILER, TRANSACTION_TRAILER, GitCommitRecord,\n)\n\n\ndef _json_bytes(value):\n    return (json.dumps(value, indent=2) + "\\n").encode("utf-8")\n\n\ndef _meta(revision: int, time: str):\n    return _json_bytes({\n        "schema": "meta", "campaign_id": "test-campaign", "game": "jianghu",\n        "revision": revision, "time": time, "player_id": "pc.test",\n    })\n\n\nTX148 = "tx.gameplay." + "a" * 64\nTX149 = "tx.gameplay." + "b" * 64\nTX150 = "tx.gameplay." + "c" * 64\nBASE147 = "1" * 40\nCOMMIT148 = "2" * 40\nCOMMIT149 = "3" * 40\nCOMMIT150 = "4" * 40\nHEAD = "5" * 40\n\n\nclass _Repository:\n    def __init__(self, root: Path):\n        self.root = root\n        self.files = {\n            "state/meta.json": _meta(150, "SE-0061-09-28T01:02:18"),\n            "state/a.json": _json_bytes({"value": "damaged-148"}),\n            "state/b.json": _json_bytes({"value": "damaged-149"}),\n            "state/c.json": _json_bytes({"value": "damaged-150"}),\n            "state/untouched.json": _json_bytes({"value": "keep"}),\n        }\n\n    def read_optional_bytes(self, path):\n        return self.files.get(str(path))\n\n    def read_bytes(self, path):\n        value = self.read_optional_bytes(path)\n        if value is None:\n            raise FileNotFoundError(str(path))\n        return value\n\n    def read_json(self, path):\n        return json.loads(self.read_bytes(path).decode("utf-8"))\n\n    def digest(self, path):\n        value = self.read_optional_bytes(path)\n        return None if value is None else hashlib.sha256(value).hexdigest()\n\n    def require_campaign(self, expected, path="state/meta.json"):\n        actual = self.read_json(path)["campaign_id"]\n        if actual != expected:\n            raise ValueError("campaign mismatch")\n        return actual\n\n    def require_revision(self, expected, path="state/meta.json"):\n        from shinobi_runtime.tx.errors import StaleRevisionError\n        actual = self.read_json(path)["revision"]\n        if actual != expected:\n            raise StaleRevisionError(expected, actual)\n        return actual\n\n\nclass _Git:\n    def __init__(self):\n        self.records = {\n            TX148: GitCommitRecord(\n                commit_hash=COMMIT148, paths=("state/a.json", "state/meta.json"),\n                trailers={TRANSACTION_TRAILER: TX148, CAMPAIGN_TRAILER: "test-campaign", REVISION_TRAILER: "148", MODE_TRAILER: "gameplay"},\n            ),\n            TX149: GitCommitRecord(\n                commit_hash=COMMIT149, paths=("state/b.json", "state/meta.json"),\n                trailers={TRANSACTION_TRAILER: TX149, CAMPAIGN_TRAILER: "test-campaign", REVISION_TRAILER: "149", MODE_TRAILER: "gameplay"},\n            ),\n            TX150: GitCommitRecord(\n                commit_hash=COMMIT150, paths=("state/c.json", "state/meta.json"),\n                trailers={TRANSACTION_TRAILER: TX150, CAMPAIGN_TRAILER: "test-campaign", REVISION_TRAILER: "150", MODE_TRAILER: "gameplay"},\n            ),\n        }\n        self.parents = {COMMIT148: BASE147, COMMIT149: COMMIT148, COMMIT150: COMMIT149}\n        self.files = {\n            BASE147: {\n                "state/meta.json": _meta(147, "SE-0061-09-28T00:53:58"),\n                "state/a.json": _json_bytes({"value": "clean-a"}),\n                "state/b.json": _json_bytes({"value": "clean-b"}),\n                "state/c.json": _json_bytes({"value": "clean-c"}),\n            },\n            COMMIT148: {"state/meta.json": _meta(148, "t148")},\n            COMMIT149: {"state/meta.json": _meta(149, "t149")},\n            COMMIT150: {"state/meta.json": _meta(150, "t150")},\n        }\n\n    def head(self):\n        return HEAD\n\n    def assert_pristine(self):\n        return None\n\n    def find_transaction_commit(self, transaction_id):\n        return self.records.get(transaction_id)\n\n    def is_ancestor(self, ancestor, descendant):\n        return descendant == HEAD and ancestor in {COMMIT148, COMMIT149, COMMIT150}\n\n    def tree_oid(self, commit, path):\n        assert path == "state"\n        if commit in {HEAD, COMMIT150}:\n            return "state-tree-150"\n        raise AssertionError(commit)\n\n    def first_parent(self, commit):\n        return self.parents[commit]\n\n    def read_path_at(self, commit, path):\n        return self.files.get(commit, {}).get(path)\n\n\nclass _Coordinator:\n    def __init__(self, git):\n        self.git = git\n\n\nclass _Operations:\n    def __init__(self, repository, git):\n        self.repository = repository\n        self.coordinator = _Coordinator(git)\n        self.allowed_actor_ids = frozenset({"pc.test"})\n\n    def _locked(self):\n        return nullcontext()\n\n    def _read_fingerprint(self):\n        return HEAD, "root"\n\n    def _require_read_only(self, before, code):\n        assert before == (HEAD, "root")\n\n\ndef _command(ids=None):\n    if ids is None:\n        ids = [TX148, TX149, TX150]\n    return CommandEnvelope(\n        campaign_id="test-campaign", request_id="repair.rev148-150.test", actor_id="pc.test",\n        command_type=REPAIR_COMMAND_TYPE, expected_revision=150, submitted_at="2026-08-30T23:30:00Z",\n        payload={"damaged_transaction_ids": ids}, mode="repair",\n    )\n\n\ndef test_chain_repair_restores_union_from_parent_of_oldest_and_advances_once(tmp_path):\n    repository = _Repository(tmp_path)\n    service = CampaignRepairService(_Operations(repository, _Git()))\n\n    plan = service._build(_command())\n\n    assert set(plan.writes) == {"state/a.json", "state/b.json", "state/c.json", "state/meta.json"}\n    assert json.loads(plan.writes["state/a.json"].decode()) == {"value": "clean-a"}\n    assert json.loads(plan.writes["state/b.json"].decode()) == {"value": "clean-b"}\n    assert json.loads(plan.writes["state/c.json"].decode()) == {"value": "clean-c"}\n    repaired_meta = json.loads(plan.writes["state/meta.json"].decode())\n    assert repaired_meta["revision"] == 151\n    assert repaired_meta["time"] == "SE-0061-09-28T00:53:58"\n    assert plan.result["repair_kind"] == "forward_transaction_chain_repair"\n    assert plan.result["damaged_revision_start"] == 148\n    assert plan.result["damaged_revision_end"] == 150\n    assert plan.result["restored_state_revision"] == 147\n    assert plan.result["damaged_transaction_ids"] == [TX148, TX149, TX150]\n    assert plan.result["restore_commit"] == BASE147\n    assert "state/untouched.json" not in plan.writes\n\n\ndef test_chain_repair_rejects_skipping_an_intermediate_revision(tmp_path):\n    service = CampaignRepairService(_Operations(_Repository(tmp_path), _Git()))\n    with pytest.raises(OperationError) as caught:\n        service._build(_command([TX148, TX150]))\n    assert caught.value.code == "repair_provenance_invalid"\n\n\ndef test_chain_repair_rejects_wrong_order_even_when_all_ids_are_real(tmp_path):\n    service = CampaignRepairService(_Operations(_Repository(tmp_path), _Git()))\n    with pytest.raises(OperationError) as caught:\n        service._build(_command([TX149, TX148, TX150]))\n    assert caught.value.code == "repair_provenance_invalid"\n\n\ndef test_chain_payload_rejects_duplicates_and_is_bounded(tmp_path):\n    service = CampaignRepairService(_Operations(_Repository(tmp_path), _Git()))\n    with pytest.raises(OperationError) as caught:\n        service._build(_command([TX148, TX148, TX150]))\n    assert caught.value.code == "repair_payload_invalid"\n\n    too_many = ["tx.gameplay." + f"{index:064x}" for index in range(33)]\n    with pytest.raises(OperationError) as caught:\n        service._build(_command(too_many))\n    assert caught.value.code == "repair_payload_invalid"\n''', encoding="utf-8")

print("forward repair chain patch staged")
